function dashboardAnalytics(){
 const by=(key)=>[...new Set(cases.map(c=>c[key]))].map(label=>({label,n:cases.filter(c=>c[key]===label).length})).sort((a,b)=>b.n-a.n);
 const bars=(items)=>{const max=Math.max(1,...items.map(x=>x.n));return `<div class="barChart">${items.map(x=>`<div class="chartRow"><span title="${esc(x.label)}">${esc(x.label)}</span><div class="barTrack"><div class="barFill" style="width:${(100*x.n/max).toFixed(0)}%"></div></div><b>${x.n}</b></div>`).join('')}</div>`};
 const totalParts=cases.flatMap(c=>c.parts),approved=totalParts.filter(p=>p.decision==='approved').length,rejected=totalParts.filter(p=>p.decision==='rejected').length;
 const regions=by('region'), brands=by('brand').slice(0,6),states=by('state').slice(0,8);
 const monthly=[{label:'Jun',n:6},{label:'Jul',n:11},{label:'Ago',n:17},{label:'Sep',n:24},{label:'Oct',n:cases.length}];
 const topModels=[...new Set(cases.map(c=>c.model.split(' Serie ')[0]))].map(label=>({label,n:cases.filter(c=>c.model.startsWith(label)).length})).sort((a,b)=>b.n-a.n).slice(0,5);
 const groupRows=corporateGroups.map(g=>({label:g.label,n:groupCaseCount(g)})).sort((a,b)=>b.n-a.n);
 return `<div class="analyticsHeading"><div><span class="eyebrow">ANÁLISIS EN UNA VISTA</span><h2>Indicadores de desempeño</h2><p class="muted">Visualizaciones ilustrativas para identificar tendencias; no son métricas reales de Celsius.</p></div></div>
 <div class="metricsTiles"><div><span>Refacciones reclamadas</span><strong>${totalParts.length}</strong><small>En ${cases.length} expedientes</small></div><div><span>Piezas aprobadas</span><strong>${approved}</strong><small>${totalParts.length?Math.round(approved/totalParts.length*100):0}% del total</small></div><div><span>Piezas rechazadas</span><strong>${rejected}</strong><small>Dictámenes de ejemplo</small></div><div><span>Tiempo medio</span><strong>${(cases.reduce((n,c)=>n+c.days,0)/cases.length).toFixed(1)} días</strong><small>Valor ilustrativo</small></div></div>
 <div class="dashboardCharts"><section class="panel"><div class="chartTitle"><h2>Evolución de solicitudes</h2><span class="tagNeutral">Últimos 5 meses · muestra</span></div>${bars(monthly)}</section><section class="panel"><h2>Estados de los folios</h2>${bars(states)}</section><section class="panel"><h2>Garantías por marca</h2>${bars(brands)}</section><section class="panel"><h2>Concentración por región</h2>${bars(regions)}</section><section class="panel"><h2>Modelos con más reportes</h2>${bars(topModels)}</section><section class="panel"><h2>Empresas consolidadas</h2>${groupRows.length?bars(groupRows):'<p class="muted">Sin agrupaciones</p>'}<p class="hint">Las vinculaciones se administran únicamente en Cuentas y empresas.</p></section></div>`;
}

